using System;
class CreditsScrollTests {static void Equal(float a,float b,string name){if(Math.Abs(a-b)>.01f)throw new Exception(name+": "+a+" != "+b);}static int Main(){Equal(CreditsScroll.Reveal(0,714.4f,428,506,856),0,"visible row must not move before mouse release");Equal(CreditsScroll.Reveal(0,714.4f,764,842,856),127.6f,"minimal bottom reveal");Equal(CreditsScroll.Reveal(128,714.4f,8,86,856),8,"minimal top reveal");Equal(CreditsScroll.Reveal(80,714.4f,428,506,856),80,"visible selection preserves scroll");Equal(CreditsScroll.Reveal(0,714.4f,8,86,300),0,"short content stays still");Console.WriteLine("PASS 5 credits selection-scroll regressions");return 0;}}
